<?php require_once __DIR__.'/config/db.php';if(!empty($_SESSION['user_id'])) redirect('account.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$password=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=? AND role="customer"');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$next=$_GET['next']??$_POST['next']??'account.php';redirect($next);}else{$error='Email or password is incorrect.';}}$page_title='Login — MediNova';require __DIR__.'/includes/store_header.php';?><section class="form-page"><div class="form-shell"><p class="kicker">CUSTOMER ACCOUNT</p><h1>Welcome back.</h1><?php if($error):?><div class="admin-alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="next" value="<?=e($_GET['next']??'account.php')?>"><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" required></div><button class="btn btn-light">Login ↗</button></form><p style="color:#858e86;margin-top:25px">New here? <a style="color:var(--acid)" href="register.php">Create a customer account</a></p></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
